const wrap=(fn:(req:any,res:any)=>Promise<any>)=>(req:any,res:any,next:any)=>Promise.resolve(fn(req,res)).catch(next);
async function scope(req:any,res:any,permission:"admissions.read"|"admissions.manage"="admissions.read"){
 const organizationId=String(req.params.organizationId||""), schoolId=String(req.params.schoolId||""), userId=req.auth!.userId;
 if(!await hasActiveSchoolMembership(userId,organizationId,schoolId)){res.status(403).json({error:"Active school membership required"});return null;}
 if(!await hasSchoolPermission(userId,organizationId,schoolId,permission)){res.status(403).json({error:`Missing required permission: ${permission}`});return null;}
 if(!await entitled({organizationId,schoolId,userId})){res.status(402).json({error:"Admissions feature not included in subscription"});return null;}
 return {organizationId,schoolId,userId};
}
async function entitled(s:any){
 return withTenantContext(prisma,s,async tx=>{
  const sub=await tx.organizationSubscription.findFirst({where:{organizationId:s.organizationId,status:{in:["TRIALING","ACTIVE","PAST_DUE"]},currentPeriodEndsAt:{gt:new Date()}},orderBy:{createdAt:"desc"}});
  if(!sub)return false; const p=await tx.subscriptionPlan.findUnique({where:{id:sub.planId}});
  return (p?.entitlements as any)?.admissions===true;
 });
}
