admissionRouter.get(base+"/foundation",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.read");if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{const [academicYears,gradeLevels,ruleCount,applicationCount]=await Promise.all([tx.academicYear.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},select:{id:true,name:true,code:true,status:true,isCurrent:true,startsOn:true,endsOn:true},orderBy:{startsOn:"desc"}}),tx.gradeLevel.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,isActive:true},select:{id:true,code:true,name:true,sequence:true,stage:true},orderBy:{sequence:"asc"}}),tx.admissionEligibilityRule.count({where:{organizationId:s.organizationId,schoolId:s.schoolId,enabled:true}}),tx.admissionApplication.count({where:{organizationId:s.organizationId,schoolId:s.schoolId}})]);return {academicYears,gradeLevels,supportedBoards:["CBSE","ICSE","STATE","IB","IGCSE","OTHER"],applicationStatuses:["DRAFT","SUBMITTED","UNDER_REVIEW","DOCUMENTS_PENDING","APPROVED","OFFERED","ACCEPTED","REJECTED","WITHDRAWN","CONVERTED"],setupReadiness:{academicYearsConfigured:academicYears.length>0,gradeLevelsConfigured:gradeLevels.length>0,eligibilityRulesConfigured:ruleCount>0,applicationRecordsExist:applicationCount>0},counts:{academicYears:academicYears.length,activeGradeLevels:gradeLevels.length,enabledEligibilityRules:ruleCount,applications:applicationCount}}});return res.json({data});}));
