admissionRouter.patch(base+"/applications/:applicationId/reviewer",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const p=z.object({reviewerId:z.string().trim().min(1).max(128).nullable(),reason:z.string().trim().max(500).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid reviewer assignment"});const data=await withTenantContext(prisma,s,async tx=>{const a=await tx.admissionApplication.findFirst({where:{id:req.params.applicationId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!a)throw Object.assign(new Error("Application not found"),{status:404});if(p.data.reviewerId){const membership=await tx.schoolMembership.findFirst({where:{userId:p.data.reviewerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"}});const user=await tx.user.findFirst({where:{id:p.data.reviewerId,isActive:true}});if(!membership||!user)throw Object.assign(new Error("Reviewer must be an active member of this school"),{status:400});}if(a.assignedReviewerId===p.data.reviewerId)return a;const updated=await tx.admissionApplication.update({where:{id:a.id},data:{assignedReviewerId:p.data.reviewerId}});await tx.admissionReviewerAssignmentHistory.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:a.id,previousReviewerId:a.assignedReviewerId,newReviewerId:p.data.reviewerId,actorUserId:s.userId,reason:p.data.reason||null}});await notifyAdmissionStaffEvent(tx,{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:a.id,eventKey:`reviewer-assigned:${a.id}:${updated.updatedAt.toISOString()}`,title:"Admission reviewer assignment updated",body:`Reviewer assignment changed for application ${a.applicationNumber}.`,applicationNumber:a.applicationNumber});return updated;});return res.json({data});}));
