admissionRouter.get(base+"/exceptions",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.read");if(!s)return;const now=new Date();const activeStatuses=["SUBMITTED","UNDER_REVIEW","DOCUMENTS_PENDING"];const thresholds:any={SUBMITTED:24,UNDER_REVIEW:48,DOCUMENTS_PENDING:48};const data=await withTenantContext(prisma,s,async tx=>{const [apps,offers,reservations,docs]=await Promise.all([tx.admissionApplication.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:{in:activeStatuses}},select:{id:true,applicationNumber:true,childFirstName:true,childLastName:true,status:true,assignedReviewerId:true,createdAt:true,updatedAt:true,submittedAt:true}}),tx.admissionOffer.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED",expiresAt:{lt:now}},select:{id:true,offerNumber:true,applicationId:true,status:true,expiresAt:true}}),tx.admissionSeatReservation.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE",expiresAt:{lt:now}},select:{id:true,applicationId:true,offerId:true,status:true,expiresAt:true}}),tx.admissionApplicationDocument.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,OR:[{status:"REJECTED"},{securityStatus:"REJECTED"},{securityStatus:"QUARANTINED"}]},select:{id:true,applicationId:true,documentType:true,displayName:true,status:true,securityStatus:true,createdAt:true}})]);const histories=apps.length?await tx.admissionStageHistory.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:{in:apps.map(a=>a.id)}},select:{applicationId:true,toStatus:true,createdAt:true},orderBy:{createdAt:"desc"}}):[];const stageStart=new Map<string,Date>();for(const h of histories){const app=apps.find(a=>a.id===h.applicationId);if(app&&app.status===h.toStatus&&!stageStart.has(h.applicationId))stageStart.set(h.applicationId,h.createdAt);}const exceptions:any[]=[];for(const a of apps){if(!a.assignedReviewerId)exceptions.push({id:`unassigned:${a.id}`,type:"UNASSIGNED_REVIEWER",severity:"HIGH",applicationId:a.id,applicationNumber:a.applicationNumber,applicantName:[a.childFirstName,a.childLastName].filter(Boolean).join(" "),status:a.status,createdAt:a.createdAt,summary:"Active application has no reviewer assigned",action:"Assign reviewer"});const hours=thresholds[a.status]||48,start=stageStart.get(a.id)||a.submittedAt||a.updatedAt||a.createdAt,due=new Date(start.getTime()+hours*3600000);if(now>due)exceptions.push({id:`sla:${a.id}`,type:"REVIEW_SLA_OVERDUE",severity:"HIGH",applicationId:a.id,applicationNumber:a.applicationNumber,applicantName:[a.childFirstName,a.childLastName].filter(Boolean).join(" "),status:a.status,dueAt:due.toISOString(),summary:`Review stage exceeded ${hours}-hour SLA`,action:"Open application"});}for(const o of offers)exceptions.push({id:`offer:${o.id}`,type:"OFFER_EXPIRED",severity:"MEDIUM",applicationId:o.applicationId,offerNumber:o.offerNumber,expiresAt:o.expiresAt,summary:"Offer is past its expiry date but remains OFFERED",action:"Review offer"});for(const r of reservations)exceptions.push({id:`reservation:${r.id}`,type:"RESERVATION_EXPIRED",severity:"HIGH",applicationId:r.applicationId,offerId:r.offerId,expiresAt:r.expiresAt,summary:"Active seat reservation is past expiry",action:"Review reservation"});for(const d of docs)exceptions.push({id:`document:${d.id}`,type:"DOCUMENT_EXCEPTION",severity:d.securityStatus==="QUARANTINED"?"HIGH":"MEDIUM",applicationId:d.applicationId,documentId:d.id,documentType:d.documentType,displayName:d.displayName,status:d.status,securityStatus:d.securityStatus,createdAt:d.createdAt,summary:"Admission document requires recovery or security review",action:"Review document"});const severityOrder={HIGH:0,MEDIUM:1,LOW:2};exceptions.sort((a,b)=>(severityOrder[a.severity as keyof typeof severityOrder]??9)-(severityOrder[b.severity as keyof typeof severityOrder]??9));return {generatedAt:now.toISOString(),summary:{total:exceptions.length,high:exceptions.filter(e=>e.severity==="HIGH").length,medium:exceptions.filter(e=>e.severity==="MEDIUM").length,unassigned:exceptions.filter(e=>e.type==="UNASSIGNED_REVIEWER").length,overdueSla:exceptions.filter(e=>e.type==="REVIEW_SLA_OVERDUE").length,expiredOffers:exceptions.filter(e=>e.type==="OFFER_EXPIRED").length,expiredReservations:exceptions.filter(e=>e.type==="RESERVATION_EXPIRED").length,documentIssues:exceptions.filter(e=>e.type==="DOCUMENT_EXCEPTION").length},exceptions};});return res.json({data});}));
