// P335: school-scoped reviewer workload and SLA overview. SLA thresholds are explicit Cycle 1 defaults.
admissionRouter.get(base+"/reviewer-workload",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.read");if(!s)return;const now=new Date();const activeStatuses=["SUBMITTED","UNDER_REVIEW","DOCUMENTS_PENDING"];const thresholds:any={SUBMITTED:24,UNDER_REVIEW:48,DOCUMENTS_PENDING:48};const data=await withTenantContext(prisma,s,async tx=>{const [memberships,apps]=await Promise.all([tx.schoolMembership.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{userId:true}}),tx.admissionApplication.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:{in:activeStatuses}},select:{id:true,applicationNumber:true,childFirstName:true,childLastName:true,status:true,assignedReviewerId:true,createdAt:true,updatedAt:true,submittedAt:true}})]);const ids=memberships.map(m=>m.userId);const users=ids.length?await tx.user.findMany({where:{id:{in:ids},isActive:true},select:{id:true,displayName:true,email:true}}):[];const histories=apps.length?await tx.admissionStageHistory.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:{in:apps.map(a=>a.id)}},select:{applicationId:true,toStatus:true,createdAt:true},orderBy:{createdAt:"desc"}}):[];const stageStartByApp=new Map<string,Date>();for(const h of histories){const current=apps.find(a=>a.id===h.applicationId);if(current&&current.status===h.toStatus&&!stageStartByApp.has(h.applicationId))stageStartByApp.set(h.applicationId,h.createdAt);}const userMap=new Map(users.map(u=>[u.id,u]));const rows=apps.map(a=>{const hours=thresholds[a.status]||48;const stageStartedAt=stageStartByApp.get(a.id)||a.submittedAt||a.updatedAt||a.createdAt;const ageHours=Math.max(0,(now.getTime()-stageStartedAt.getTime())/3600000);const dueAt=new Date(stageStartedAt.getTime()+hours*3600000);return {...a,stageStartedAt:stageStartedAt.toISOString(),reviewer:userMap.get(a.assignedReviewerId||"")||null,ageHours:Math.round(ageHours*10)/10,slaHours:hours,dueAt:dueAt.toISOString(),overdue:now>dueAt};});const workload=users.map(u=>{const items=rows.filter(r=>r.assignedReviewerId===u.id);return {reviewer:u,activeCount:items.length,overdueCount:items.filter(i=>i.overdue).length,oldestAgeHours:items.length?Math.max(...items.map(i=>i.ageHours)):0};}).sort((a,b)=>b.activeCount-a.activeCount||b.overdueCount-a.overdueCount);return {summary:{activeCount:rows.length,unassignedCount:rows.filter(r=>!r.assignedReviewerId).length,overdueCount:rows.filter(r=>r.overdue).length,inactiveReviewerAssignmentCount:rows.filter(r=>r.assignedReviewerId&&!r.reviewer).length,submittedCount:rows.filter(r=>r.status==="SUBMITTED").length,inReviewCount:rows.filter(r=>r.status==="UNDER_REVIEW").length,documentsPendingCount:rows.filter(r=>r.status==="DOCUMENTS_PENDING").length},workload,applications:rows.sort((a,b)=>b.ageHours-a.ageHours),slaThresholdHours:thresholds};});return res.json({data});}));
