admissionRouter.post(base+"/enquiries/:enquiryId/convert",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const p=z.object({applicationNumber:z.string().trim().min(1).max(40),academicYearId:z.string().min(1),gradeLevelId:z.string().min(1),boardCode:z.string().trim().max(30).optional(),dateOfBirth:z.string().date().optional(),gender:z.string().max(40).optional(),guardianRelationship:z.string().max(40).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid conversion details",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const e=await tx.admissionEnquiry.findFirst({where:{id:req.params.enquiryId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!e)throw Object.assign(new Error("Enquiry not found"),{status:404});if(e.status==="CONVERTED")throw Object.assign(new Error("Enquiry already converted"),{status:409});const created=await tx.admissionApplication.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,applicationNumber:p.data.applicationNumber,academicYearId:p.data.academicYearId,gradeLevelId:p.data.gradeLevelId,boardCode:p.data.boardCode,childFirstName:e.childFirstName,childLastName:e.childLastName,dateOfBirth:p.data.dateOfBirth?new Date(p.data.dateOfBirth+"T00:00:00Z"):undefined,gender:p.data.gender,guardianName:e.guardianName,guardianEmail:e.guardianEmail,guardianPhone:e.guardianPhone,guardianRelationship:p.data.guardianRelationship,createdBy:s.userId}});await tx.admissionStageHistory.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:created.id,toStatus:"DRAFT",actorUserId:s.userId,note:`Converted from enquiry ${e.id}`}});await tx.admissionEnquiry.update({where:{id:e.id},data:{status:"CONVERTED"}});return created;});return res.status(201).json({data});}));
