function ageMonthsAt(dob:Date,cutoff:Date){let months=(cutoff.getUTCFullYear()-dob.getUTCFullYear())*12+(cutoff.getUTCMonth()-dob.getUTCMonth());if(cutoff.getUTCDate()<dob.getUTCDate())months--;return months;}

