// P339: extend an active seat hold while keeping reservation and offer expiry synchronized.
admissionRouter.post(base+"/reservations/:reservationId/extend",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const p=z.object({expiresAt:z.string().datetime()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"A valid reservation expiry timestamp is required",details:p.error.flatten()});const now=new Date(),expiresAt=new Date(p.data.expiresAt);if(expiresAt.getTime()<=now.getTime()+5*60*1000||expiresAt.getTime()>now.getTime()+30*24*60*60*1000)return res.status(400).json({error:"Expiry must be at least 5 minutes and no more than 30 days from now"});const data=await withTenantContext(prisma,s,async tx=>{const r=await tx.admissionSeatReservation.findFirst({where:{id:req.params.reservationId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE",OR:[{expiresAt:null},{expiresAt:{gt:now}}]}});if(!r)throw Object.assign(new Error("Active, unexpired reservation not found"),{status:404});const offer=await tx.admissionOffer.findFirst({where:{id:r.offerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"}});if(!offer)throw Object.assign(new Error("Reservation offer is not open"),{status:409});const changed=await tx.admissionSeatReservation.updateMany({where:{id:r.id,status:"ACTIVE",OR:[{expiresAt:null},{expiresAt:{gt:now}}]},data:{expiresAt}});if(!changed.count)throw Object.assign(new Error("Reservation changed concurrently; refresh and retry"),{status:409});const offerChanged=await tx.admissionOffer.updateMany({where:{id:offer.id,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"},data:{expiresAt}});if(!offerChanged.count)throw Object.assign(new Error("Offer changed concurrently; refresh and retry"),{status:409});return {reservationId:r.id,status:"ACTIVE",expiresAt};});return res.json({data});}));
admissionRouter.post(base+"/reservations/:reservationId/release",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const p=z.object({reason:z.string().trim().min(3).max(300)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Release reason is required",details:p.error.flatten()});const now=new Date();const data=await withTenantContext(prisma,s,async tx=>{const r=await tx.admissionSeatReservation.findFirst({where:{id:req.params.reservationId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"}});if(!r)throw Object.assign(new Error("Active reservation not found"),{status:404});const offer=await tx.admissionOffer.findFirst({where:{id:r.offerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"}});if(!offer)throw Object.assign(new Error("Only reservations for open offers can be manually released"),{status:409});const changed=await tx.admissionSeatReservation.updateMany({where:{id:r.id,status:"ACTIVE"},data:{status:"RELEASED",releasedAt:now,releaseReason:p.data.reason}});if(!changed.count)throw Object.assign(new Error("Reservation already released"),{status:409});await tx.gradeSectionCapacity.updateMany({where:{id:r.capacityId,reservedSeats:{gt:0}},data:{reservedSeats:{decrement:1}}});await tx.admissionOffer.updateMany({where:{id:r.offerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"},data:{status:"WITHDRAWN"}});return {reservationId:r.id,status:"RELEASED",releasedAt:now,reason:p.data.reason};});return res.json({data});}));
