admissionRouter.post(base+"/reservations/release-expired",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const now=new Date();const data=await withTenantContext(prisma,s,async tx=>{const expired=await tx.admissionSeatReservation.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE",expiresAt:{lte:now}}});let released=0;for(const r of expired){const updated=await tx.admissionSeatReservation.updateMany({where:{id:r.id,status:"ACTIVE"},data:{status:"EXPIRED",releasedAt:now,releaseReason:"Offer expired"}});if(updated.count){await tx.gradeSectionCapacity.updateMany({where:{id:r.capacityId,reservedSeats:{gt:0}},data:{reservedSeats:{decrement:1}}});await tx.admissionOffer.updateMany({where:{id:r.offerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"},data:{status:"EXPIRED"}});released++;}}return {releasedCount:released};});return res.json({data});}));
