admissionRouter.post(base+"/offers/:offerId/respond",wrap(async(req,res)=>{const s=await scope(req,res,"admissions.manage");if(!s)return;const p=z.object({decision:z.enum(["ACCEPTED","DECLINED"])}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid decision"});const data=await withTenantContext(prisma,s,async tx=>{const o=await tx.admissionOffer.findFirst({where:{id:req.params.offerId,organizationId:s.organizationId,schoolId:s.schoolId,status:"OFFERED"}});if(!o)throw Object.assign(new Error("Open offer not found"),{status:404});if(o.expiresAt&&o.expiresAt<new Date()){const r=await tx.admissionSeatReservation.findUnique({where:{offerId:o.id}});if(r?.status==="ACTIVE"){await tx.gradeSectionCapacity.update({where:{id:r.capacityId},data:{reservedSeats:{decrement:1}}});await tx.admissionSeatReservation.update({where:{id:r.id},data:{status:"EXPIRED",releasedAt:new Date(),releaseReason:"Offer expired"}});}await tx.admissionOffer.update({where:{id:o.id},data:{status:"EXPIRED"}});throw Object.assign(new Error("Offer has expired"),{status:409});}const updated=await tx.admissionOffer.update({where:{id:o.id},data:{status:p.data.decision,acceptedAt:p.data.decision==="ACCEPTED"?new Date():undefined}});const nextApplicationStatus=p.data.decision==="ACCEPTED"?"ACCEPTED":"WITHDRAWN";if(p.data.decision==="DECLINED"){const r=await tx.admissionSeatReservation.findUnique({where:{offerId:o.id}});if(r?.status==="ACTIVE"){await tx.gradeSectionCapacity.update({where:{id:r.capacityId},data:{reservedSeats:{decrement:1}}});await tx.admissionSeatReservation.update({where:{id:r.id},data:{status:"RELEASED",releasedAt:new Date(),releaseReason:"Offer declined"}});}}await tx.admissionApplication.update({where:{id:o.applicationId},data:{status:nextApplicationStatus}});await tx.admissionStageHistory.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,applicationId:o.applicationId,fromStatus:"OFFERED",toStatus:nextApplicationStatus,actorUserId:s.userId,note:p.data.decision==="DECLINED"?"Offer declined":undefined}});return updated});return res.json({data});}));

